# 位掩码型枚举（值按位相加 = 加法合成）：
#   Units.Type             2 步兵/4 载具/8 直升机/16 飞机/32 舰船/128 弹丸/256 反辐射/512 巡航/1024 弹道
#   Ammunitions.TargetType 1 地面/2 步兵/4 载具/8 直升机/16 飞机/32 舰船/128 弹丸/256 反辐射/512 巡航/1024 弹道
# 例：36 = 32(舰船) + 4(载具)。
MASK_ENUMS = {"Units.Type", "Ammunitions.TargetType"}


def enum_note(key, lang="zh"):
    """该枚举的「真实作用」说明；无则返回空串。key 形如 'Units.Role'。"""
    note = ENUM_NOTES.get(key)
    if not isinstance(note, dict):
        return ""
    return note.get(lang) or note.get("en") or note.get("zh") or ""


def enum_members(field):
    """{值(str): 枚举成员名(str)}；成员名取自 dump.cs 反编译结果（第 5 列）。"""
    out = {}
    for item in ENUMS.get(field) or []:
        if isinstance(item, (list, tuple)) and len(item) >= 5 and item[4]:
            out[str(item[0])] = str(item[4])
    return out


def enum_member(field, value):
    """单个值的枚举成员名（如 11 → 'Tank'），无则空串。value 可为 int/str。"""
    return enum_members(field).get(str(value), "")


def enum_is_mask(key):
    """该枚举是不是位掩码（值按位相加，如 Ammunitions.TargetType / Units.Type）。"""
    return key in MASK_ENUMS


def enum_mask_parts(key, value, lang="zh"):
    """拆解位掩码 → ([(bit, 含义)], 未知位)。

    只认 2 的整数次幂的枚举行（位定义）；未知位 = 值里剩下的、游戏没定义的位。
    例：('Ammunitions.TargetType', 36) → ([(32, '舰船'), (4, '载具')], 0)（按位从大到小）。
    """
    try:
        value = int(value)
    except (TypeError, ValueError):
        return [], 0
    bits = []
    for vs, meaning in enum_values(key, lang):
        try:
            v = int(str(vs).strip())
        except (TypeError, ValueError):
            continue
        if v <= 0 or (v & (v - 1)) != 0:  # 只保留单 bit
            continue
        if value & v:
            bits.append((v, meaning or str(v)))
    bits.sort(key=lambda x: -x[0])  # 从高位到低位，读起来就是 32 + 4
    known = 0
    for v, _ in bits:
        known |= v
    return bits, (value & ~known)


def enum_mask_label(key, value, lang="zh", with_numbers=True):
    """位掩码的拆解文本：36 → '舰船 + 载具 (32 + 4)'；0 / 无法拆解时返回空串。"""
    bits, unknown = enum_mask_parts(key, value, lang)
    if not bits and not unknown:
        return ""
    parts = [m for _, m in bits]
    if unknown:
        parts.append("未知位 %d" % unknown)
    text = " + ".join(parts)
    if with_numbers and len(bits) > 1:
        text += " (%s)" % " + ".join(str(v) for v, _ in bits)
    return text


def enum_key(table, field):
    """(表, 字段) → 枚举键 'Table.Field'（不在 ENUMS 里则返回 None）。

    用于 GUI：判断某字段是不是枚举字段、该显示哪张对照表。"""
    if not table or not field:
        return None
    key = "%s.%s" % (table, field)
    return key if key in ENUMS else None


def enum_meaning(key, value, lang="zh"):
    """枚举值的含义（如 ('Units.Role', 11).zh → '主战坦克'）；未知值返回空串。"""
    for val, meaning in enum_values(key, lang):
        if str(val) == str(value):
            return meaning or ""
    return ""


def enum_label(key, value, lang="zh"):
    """绿色箭头用的短标签。

    - 普通枚举：'主战坦克 (Tank)'（成员名来自 dump.cs）
    - 位掩码枚举：'舰船 + 载具 (32 + 4)'（按位相加拆解）
    - 未知值 / 无法拆解：返回空串，由调用方给出告警文案
    """
    if enum_is_mask(key):
        text = enum_mask_label(key, value, lang)
        if text:
            return text
        # 0 或空值 → 回落到普通查表（0 = '无'）
    meaning = enum_meaning(key, value, lang)
    if not meaning:
        return ""
    member = enum_member(key, value)
    if member and member.lower() not in meaning.lower():
        return "%s (%s)" % (meaning, member)
    return meaning


def _pick(entry, lang):
    if not isinstance(entry, dict):
        return None, None
    lang_data = entry.get(lang) or entry.get("en") or entry.get("zh")
    if not lang_data:
        return None, None
    return (lang_data[0] or ""), (lang_data[1] or "")


def table_info(table, lang="zh"):
    t = TABLES.get(table)
    if t is None:
        return None
    return _pick(t, lang)


def field_info(table, field, lang="zh"):
    entry = FIELDS.get(table, {}).get(field) or COMMON.get(field)
    if entry is None:
        return None
    return _pick(entry, lang)


def enum_values(field, lang="zh"):
    entries = ENUMS.get(field)
    if not entries:
        return []
    idx = {"zh": 1, "en": 2, "ru": 3}.get(lang, 2)
    out = []
    for item in entries:
        val = item[0]
        meaning = item[idx] if idx < len(item) else ""
        if not meaning:
            meaning = item[2] or item[1] or ""
        out.append((val, meaning))
    return out
